ay_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/11/44/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/11/44/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/11/44/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/11/\",\"title\":\"Chapter Eleven: The Universal Form\"}],\"url_path\":\"/en/library/bg/11/44/\",\"bb\":2973,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/11/43/\",\"title\":\"TEXT 43\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/11/45/\",\"title\":\"TEXT 45\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3376,\"bb\":568322,\"url_path\":\"/en/library/bg/11/44/devanagari/\",\"body_final\":\"तस्मात्प्रणम्य प्रणिधाय कायं
प्रसादये त्वामहमीशमीड्यम् ।
पितेव पुत्रस्य सखेव सख्यु:
प्रिय: प्रियायार्हसि देव सोढुम् ॥ ४४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3377,\"bb\":2974,\"url_path\":\"/en/library/bg/11/44/b2974/\",\"body_value\":\"tasmāt praṇamya praṇidhāya kāyaṁ
prasādaye tvām aham īśam īḍyam
piteva putrasya sakheva sakhyuḥ
priyaḥ priyāyārhasi deva soḍhum\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3378,\"bb\":2975,\"url_path\":\"/en/library/bg/11/44/b2975/\",\"shadow_value\":\"tasmāt – therefore; praṇamya – offering obeisances; praṇidhāya – laying down; kāyam – the body; prasādaye – to beg mercy; tvām – unto You; aham – I; īśam – unto the Supreme Lord; īḍyam – worshipable; pitā iva – like a father; putrasya – with a son; sakhā iva – like a friend; sakhyuḥ – with a friend; priyaḥ – a lover; priyāyāḥ – with the dearmost; arhasi – You should; deva – my Lord; soḍhum – tolerate.\",\"word_for_word_value\":[{\"word\":\"tasmāt\",\"translation\":\"therefore\"},{\"word\":\"praṇamya\",\"translation\":\"offering obeisances\"},{\"word\":\"praṇidhāya\",\"translation\":\"laying down\"},{\"word\":\"kāyam\",\"translation\":\"the body\"},{\"word\":\"prasādaye\",\"translation\":\"to beg mercy\"},{\"word\":\"tvām\",\"translation\":\"unto You\"},{\"word\":\"aham\",\"translation\":\"I\"},{\"word\":\"īśam\",\"translation\":\"unto the Supreme Lord\"},{\"word\":\"īḍyam\",\"translation\":\"worshipable\"},{\"word\":\"pitā iva\",\"translation\":\"like a father\"},{\"word\":\"putrasya\",\"translation\":\"with a son\"},{\"word\":\"sakhā iva\",\"translation\":\"like a friend\"},{\"word\":\"sakhyuḥ\",\"translation\":\"with a friend\"},{\"word\":\"priyaḥ\",\"translation\":\"a lover\"},{\"word\":\"priyāyāḥ\",\"translation\":\"with the dearmost\"},{\"word\":\"arhasi\",\"translation\":\"You should\"},{\"word\":\"deva\",\"translation\":\"my Lord\"},{\"word\":\"soḍhum\",\"translation\":\"tolerate\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3379,\"bb\":2976,\"url_path\":\"/en/library/bg/11/44/b2976/\",\"body_value\":\"You are the Supreme Lord, to be worshiped by every living being. Thus I fall down to offer You my respectful obeisances and ask Your mercy. As a father tolerates the impudence of his son, a friend the impertinence of a friend, or a husband the familiarity of his wife, please tolerate the wrongs I may have done You.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3380,\"bb\":2977,\"url_path\":\"/en/library/bg/11/44/b2977/\",\"body_value\":\"Kṛṣṇa’s devotees relate to Kṛṣṇa in various relationships; one might treat Kṛṣṇa as a son, or one might treat Kṛṣṇa as a husband, as a friend, or as a master. Kṛṣṇa and Arjuna are related in friendship. As the father tolerates, or the husband or a master tolerates, so Kṛṣṇa tolerates.\"}]}],\"short_title\":\"Bg. 11.44\",\"medium_title\":\"Bhagavad-gītā As It Is 11.44\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\"