भयेन च प्रव्यथितं मनो मे ।
तदेव मे दर्शय देव रूपं
प्रसीद देवेश जगन्निवास ॥ ४५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3383,\"bb\":2979,\"url_path\":\"/en/library/bg/11/45/b2979/\",\"body_value\":\"adṛṣṭa-pūrvaṁ hṛṣito ’smi dṛṣṭvā
bhayena ca pravyathitaṁ mano me
tad eva me darśaya deva rūpaṁ
prasīda deveśa jagan-nivāsa\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3384,\"bb\":2980,\"url_path\":\"/en/library/bg/11/45/b2980/\",\"shadow_value\":\"adṛṣṭa-pūrvam – never seen before; hṛṣitaḥ – gladdened; asmi – I am; dṛṣṭvā – by seeing; bhayena – out of fear; ca – also; pravyathitam – perturbed; manaḥ – mind; me – my; tat – that; eva – certainly; me – unto me; darśaya – show; deva – O Lord; rūpam – the form; prasīda – just be gracious; deva-īśa – O Lord of lords; jagat-nivāsa – O refuge of the universe.\",\"word_for_word_value\":[{\"word\":\"adṛṣṭa-pūrvam\",\"translation\":\"never seen before\"},{\"word\":\"hṛṣitaḥ\",\"translation\":\"gladdened\"},{\"word\":\"asmi\",\"translation\":\"I am\"},{\"word\":\"dṛṣṭvā\",\"translation\":\"by seeing\"},{\"word\":\"bhayena\",\"translation\":\"out of fear\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"pravyathitam\",\"translation\":\"perturbed\"},{\"word\":\"manaḥ\",\"translation\":\"mind\"},{\"word\":\"me\",\"translation\":\"my\"},{\"word\":\"tat\",\"translation\":\"that\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"me\",\"translation\":\"unto me\"},{\"word\":\"darśaya\",\"translation\":\"show\"},{\"word\":\"deva\",\"translation\":\"O Lord\"},{\"word\":\"rūpam\",\"translation\":\"the form\"},{\"word\":\"prasīda\",\"translation\":\"just be gracious\"},{\"word\":\"deva-īśa\",\"translation\":\"O Lord of lords\"},{\"word\":\"jagat-nivāsa\",\"translation\":\"O refuge of the universe\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3385,\"bb\":2981,\"url_path\":\"/en/library/bg/11/45/b2981/\",\"body_value\":\"After seeing this universal form, which I have never seen before, I am gladdened, but at the same time my mind is disturbed with fear. Therefore please bestow Your grace upon me and reveal again Your form as the Personality of Godhead, O Lord of lords, O abode of the universe.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3386,\"bb\":2982,\"url_path\":\"/en/library/bg/11/45/b2982/\",\"body_value\":\"$25\"}]}],\"short_title\":\"Bg. 11.45\",\"medium_title\":\"Bhagavad-gītā As It Is 11.45\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"Bhagavad-gītā As It Is\"}],\" » \"]}],[\"$\",\"li\",