yan me tvad anyena na dṛṣṭa-pūrvam\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3396,\"bb\":2990,\"url_path\":\"/en/library/bg/11/47/b2990/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Supreme Personality of Godhead said; mayā – by Me; prasannena – happily; tava – unto you; arjuna – O Arjuna; idam – this; rūpam – form; param – transcendental; darśitam – shown; ātma-yogāt – by My internal potency; tejaḥ-mayam – full of effulgence; viśvam – the entire universe; anantam – unlimited; ādyam – original; yat – that which; me – My; tvat anyena – besides you; na dṛṣṭa-pūrvam – no one has previously seen.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Personality of Godhead said\"},{\"word\":\"mayā\",\"translation\":\"by Me\"},{\"word\":\"prasannena\",\"translation\":\"happily\"},{\"word\":\"tava\",\"translation\":\"unto you\"},{\"word\":\"arjuna\",\"translation\":\"O Arjuna\"},{\"word\":\"idam\",\"translation\":\"this\"},{\"word\":\"rūpam\",\"translation\":\"form\"},{\"word\":\"param\",\"translation\":\"transcendental\"},{\"word\":\"darśitam\",\"translation\":\"shown\"},{\"word\":\"ātma-yogāt\",\"translation\":\"by My internal potency\"},{\"word\":\"tejaḥ-mayam\",\"translation\":\"full of effulgence\"},{\"word\":\"viśvam\",\"translation\":\"the entire universe\"},{\"word\":\"anantam\",\"translation\":\"unlimited\"},{\"word\":\"ādyam\",\"translation\":\"original\"},{\"word\":\"yat\",\"translation\":\"that which\"},{\"word\":\"me\",\"translation\":\"My\"},{\"word\":\"tvat anyena\",\"translation\":\"besides you\"},{\"word\":\"na dṛṣṭa-pūrvam\",\"translation\":\"no one has previously seen\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3397,\"bb\":2991,\"url_path\":\"/en/library/bg/11/47/b2991/\",\"body_value\":\"The Supreme Personality of Godhead said: My dear Arjuna, happily have I shown you, by My internal potency, this supreme universal form within the material world. No one before you has ever seen this primal form, unlimited and full of glaring effulgence.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3398,\"bb\":2992,\"url_path\":\"/en/library/bg/11/47/b2992/\",\"body_value\":\"$25\"}]}],\"short_title\":\"Bg. 11.47\",\"medium_title\":\"Bhagavad-gītā As It Is 11.47\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\